{"title":"Snow forecast heatmap","type":"vega","aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "padding": {
    "top": 50,
    "left": 50,
    "right": 30,
    "bottom": 30
  },
  "data": [
    {
      "name": "rawData",
      "url": {
        "index": "snow-forecast",
        "body": {
          "size": 1000,
          "sort": [
            {
              "@timestamp": "desc"
            }
          ],
          "_source": [
            "@timestamp",
            "name",
            "level",
            "total_snow_cm",
            "forecasts"
          ],
          "query": {
            "bool": {
              "must": [
                "%dashboard_context-must_clause%",
                {
                  "range": {
                    "@timestamp": {
                      "%timefilter%": true
                    }
                  }
                }
              ],
              "filter": [
                "%dashboard_context-filter_clause%"
              ],
              "must_not": [
                "%dashboard_context-must_not_clause%"
              ]
            }
          }
        }
      },
      "format": {
        "property": "hits.hits"
      }
    },
    {
      "name": "latestData",
      "source": "rawData",
      "transform": [
        {
          "type": "formula",
          "expr": "datum._source.name",
          "as": "doc_name"
        },
        {
          "type": "formula",
          "expr": "datum._source.level",
          "as": "doc_level"
        },
        {
          "type": "formula",
          "expr": "datum._source['@timestamp']",
          "as": "doc_timestamp"
        },
        {
          "type": "window",
          "groupby": [
            "doc_name",
            "doc_level"
          ],
          "sort": {
            "field": "doc_timestamp",
            "order": "descending"
          },
          "ops": [
            "row_number"
          ],
          "as": [
            "run_rank"
          ]
        },
        {
          "type": "filter",
          "expr": "datum.run_rank === 1"
        }
      ]
    },
    {
      "name": "source",
      "source": "latestData",
      "transform": [
        {
          "type": "flatten",
          "fields": [
            "_source.forecasts"
          ],
          "as": [
            "forecast"
          ]
        },
        {
          "type": "formula",
          "expr": "datum._source.name",
          "as": "resort_name"
        },
        {
          "type": "formula",
          "expr": "datum.forecast.date + ' ' + datum.forecast.time",
          "as": "datetime"
        },
        {
          "type": "formula",
          "expr": "replace(datum.forecast.snow, 'cm', '')",
          "as": "snow_value"
        }
      ]
    },
    {
      "name": "unique_resorts",
      "source": "source",
      "transform": [
        {
          "type": "aggregate",
          "groupby": [
            "resort_name"
          ]
        }
      ]
    },
    {
      "name": "unique_datetimes",
      "source": "source",
      "transform": [
        {
          "type": "aggregate",
          "groupby": [
            "datetime"
          ]
        },
        {
          "type": "collect",
          "sort": {
            "field": "datetime"
          }
        }
      ]
    },
    {
      "name": "totals",
      "source": "latestData",
      "transform": [
        {
          "type": "formula",
          "expr": "datum._source.name",
          "as": "resort_name"
        },
        {
          "type": "formula",
          "expr": "'Total'",
          "as": "datetime"
        },
        {
          "type": "formula",
          "expr": "datum._source.total_snow_cm",
          "as": "total"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "y",
      "type": "band",
      "range": "height",
      "domain": {
        "data": "unique_resorts",
        "field": "resort_name",
        "sort": true
      },
      "padding": 0.2
    },
    {
      "name": "x",
      "type": "band",
      "range": "width",
      "domain": {
        "fields": [
          {
            "data": "unique_datetimes",
            "field": "datetime"
          },
          {
            "data": "totals",
            "field": "datetime"
          }
        ],
        "sort": true
      },
      "padding": 0.1
    },
    {
      "name": "color",
      "type": "linear",
      "domain": [
        0,
        50
