      "range": [
        "#eef6ff",
        "#1f77b4"
      ],
      "zero": true
    },
    {
      "name": "color_total",
      "type": "linear",
      "domain": [
        0,
        100
      ],
      "range": [
        "#eef6ff",
        "#08306b"
      ],
      "zero": true,
      "clamp": true
