      "scale": "x",
      "title": "Forecast Time",
      "labelAngle": -45,
      "labelAlign": "left",
      "encode": {
        "labels": {
          "update": {
            "text": {
              "signal": "datum.value"
            }
          }
        }
      }
    }
  ],
  "marks": [
    {
      "type": "rect",
      "from": {
        "data": "source"
      },
      "encode": {
        "enter": {
          "y": {
            "scale": "y",
            "field": "resort_name"
          },
          "height": {
            "scale": "y",
            "band": 1
          },
          "x": {
            "scale": "x",
            "field": "datetime"
          },
          "width": {
            "scale": "x",
            "band": 1
          },
          "tooltip": {
            "signal": "{'Resort': datum.resort_name, 'Level': datum._source.level, 'DateTime': datum.datetime, 'Snow': datum.forecast.snow, 'Freezing Level': datum.forecast.freezing_level + 'm', 'Humidity': datum.forecast.humidity + '%', 'Wind': datum.forecast.wind}"
          }
        },
        "update": {
          "fill": {
            "scale": "color",
            "field": "snow_value"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "source"
      },
      "encode": {
        "enter": {
          "y": {
            "scale": "y",
            "field": "resort_name",
            "band": 0.5
          },
          "x": {
            "scale": "x",
            "field": "datetime",
            "band": 0.5
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "value": 11
          },
          "text": {
            "field": "forecast.snow"
          },
          "fill": {
            "value": "black"
          }
        }
      }
    },
    {
      "type": "rect",
      "from": {
        "data": "totals"
      },
      "encode": {
        "enter": {
          "y": {
            "scale": "y",
            "field": "resort_name"
          },
          "height": {
            "scale": "y",
            "band": 1
          },
          "x": {
            "scale": "x",
            "field": "datetime"
          },
          "width": {
            "scale": "x",
            "band": 1
          },
          "stroke": {
            "value": "#08306b"
          },
          "strokeWidth": {
            "value": 1
          },
          "tooltip": {
            "signal": "{'Resort': datum.resort_name, 'Level': datum._source.level, 'Total snow': datum.total + ' cm'}"
          }
        },
        "update": {
          "fill": {
            "scale": "color_total",
            "field": "total"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "totals"
      },
      "encode": {
        "enter": {
          "y": {
            "scale": "y",
            "field": "resort_name",
            "band": 0.5
          },
          "x": {
            "scale": "x",
            "field": "datetime",
            "band": 0.5
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "value": 11
          },
          "fontWeight": {
            "value": "bold"
          },
          "text": {
            "signal": "format(datum.total, '.0f')"
          },
          "fill": {
            "signal": "datum.total > 60 ? 'white' : 'black'"
          }
        }
      }
    }
  ]
}
"}}

